{"content":"using LetUsCook.AutoWrongCensus.HostedServices;
using LetUsCook.AutoWrongCensus.Options;

using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;

using System.IO;

namespace LetUsCook.AutoWrongCensus;

/// <summary>
/// F-428 P12.13: auto-wrong census CLI — classifies every auto-wrong debug/batch line by
/// accepted-row vs key-row relation and site (reuse, override, curated, ranker).
/// </summary>
public static class AutoWrongCensusCli
{
    private const string HelpFlag = "--help";
    private const string HelpShort = "-h";

    /// <summary>
    /// Builds the host, runs the census or pairs command, and returns the exit code.
    /// </summary>
    public static async Task<int> RunAsync(string[] args, TextWriter? output = null, TextWriter? error = null)
    {
        ArgumentNullException.ThrowIfNull(args);

        output ??= Console.Out;
        error ??= Console.Error;

        if (args.Any(a => string.Equals(a, HelpFlag, StringComparison.OrdinalIgnoreCase)
                        || string.Equals(a, HelpShort, StringComparison.OrdinalIgnoreCase)))
        {
            AutoWrongCensusUsage.Print(output);
            return 0;
        }

        var builder = AutoWrongCensusHostBuilderFactory.Create(args, output, error);
        var host = builder.Build();

        var hostedService = host.Services.GetRequiredService<AutoWrongCensusHostedService>();
        await host.RunAsync().ConfigureAwait(false);
        return hostedService.ExitCode;
    }
}
