{"content":"using System.Text.Json.Serialization;

namespace LetUsCook.AutoWrongCensus.Models;

/// <summary>
/// A single holdoutGate trace line, deserialized from the JSONL produced by <c>HoldoutGate</c>.
/// Only the fields the census needs are exposed; extra fields are silently ignored.
/// </summary>
public sealed class TraceLine
{
	/// <summary>The full raw recipe line text.</summary>
	[JsonPropertyName("rawText")]
	public string RawText { get; set; } = string.Empty;

	/// <summary>Unique holdout identifier (e.g. <c>debug:recipe-abc</c>).</summary>
	[JsonPropertyName("holdoutId")]
	public string HoldoutId { get; set; } = string.Empty;

	/// <summary>Zero-based index within the recipe.</summary>
	[JsonPropertyName("lineIndex")]
	public int LineIndex { get; set; }

	/// <summary>Dataset tier: <c>Foundation</c>, <c>SrLegacy</c>, <c>Survey</c>, <c>Branded</c>.</summary>
	[JsonPropertyName("expectedDataTypes")]
	public IReadOnlyList<string> ExpectedDataTypes { get; set; } = [];

	/// <summary>USDA FDC food descriptions the line matched against.</summary>
	[JsonPropertyName("expectedDescriptions")]
	public IReadOnlyList<string> ExpectedDescriptions { get; set; } = [];

	/// <summary>Accepted row descriptions (the row that shipped).</summary>
	[JsonPropertyName("actualDescriptions")]
	public IReadOnlyList<string> ActualDescriptions { get; set; } = [];

	/// <summary>Accepted row dataset tiers.</summary>
	[JsonPropertyName("actualDataTypes")]
	public IReadOnlyList<string> ActualDataTypes { get; set; } = [];

	/// <summary>Whether the line shipped without review (auto-accepted).</summary>
	[JsonPropertyName("auto")]
	public bool Auto { get; set; }

	/// <summary>Whether the accepted row was marked correct.</summary>
	[JsonPropertyName("correct")]
	public bool Correct { get; set; }

	/// <summary>Holdout set: <c>debug</c>, <c>batch</c>, or <c>sealed</c>.</summary>
	[JsonPropertyName("set")]
	public string Set { get; set; } = string.Empty;

	/// <summary>Atoms produced by the resolver for this line.</summary>
	[JsonPropertyName("atoms")]
	public IReadOnlyList<TraceAtom> Atoms { get; set; } = [];
}

/// <summary>A single atom from the resolver pipeline.</summary>
public sealed class TraceAtom
{
	/// <summary>Decision path: <c>ranker</c>, <c>override</c>, <c>curated</c>.</summary>
	[JsonPropertyName("path")]
	public string Path { get; set; } = string.Empty;

	/// <summary>Whether the line was reused from an existing master row.</summary>
	[JsonPropertyName("reused")]
	public bool Reused { get; set; }

	/// <summary>The resolver's parsed name for this atom.</summary>
	[JsonPropertyName("parsedName")]
	public string ParsedName { get; set; } = string.Empty;

	/// <summary>The linked ingredient master slug, when one was minted.</summary>
	[JsonPropertyName("linkedIngredientId")]
	public string? LinkedIngredientId { get; set; }

	/// <summary>Outcome: <c>accepted</c>, <c>deferred</c>, or <c>rejected</c>.</summary>
	[JsonPropertyName("outcome")]
	public string Outcome { get; set; } = string.Empty;
}

/// <summary>
/// A single row from the P12.7 blocker-census TSV, used by the <c>pairs</c> subcommand.
/// </summary>
public sealed class CensusRow
{
	/// <summary>Holdout identifier (matches <see cref="TraceLine.HoldoutId"/>).</summary>
	public string HoldoutId { get; set; } = string.Empty;

	/// <summary>Line index (matches <see cref="TraceLine.LineIndex"/>).</summary>
	public int LineIndex { get; set; }

	/// <summary>Blocker type (e.g. <c>window</c>, <c>mapping-reuse</c>).</summary>
	public string Blocker { get; set; } = string.Empty;

	/// <summary>Route classification (e.g. <c>compound</c>, <c>other</c>).</summary>
	public string Route { get; set; } = string.Empty;

	/// <summary>The resolver's parsed name.</summary>
	public string ParsedName { get; set; } = string.Empty;

	/// <summary>The raw recipe line.</summary>
	public string RawText { get; set; } = string.Empty;
}

/// <summary>
/// One classified auto-wrong line: relation, site, and all TSV columns.
/// </summary>
public sealed class ClassificationResult
{
	/// <summary>Holdout identifier.</summary>
	public string HoldoutId { get; init; } = string.Empty;

	/// <summary>Line index.</summary>
	public int LineIndex { get; init; }

	/// <summary>Holdout set (debug/batch).</summary>
	public string Set { get; init; } = string.Empty;

	/// <summary>Relation class: <c>no-label</c>, <c>pack-unit-state</c>, <c>compound-head-lost</c>,
	/// <c>state-mismatch</c>, <c>row-choice-tier</c>, <c>same-head-other-qualifier</c>,
	/// <c>sibling-food</c>, or <c>other</c>.</summary>
	public string Relation { get; init; } = string.Empty;

	/// <summary>Site: <c>reuse</c>, <c>ranker</c>, <c>override</c>, <c>curated</c>.</summary>
	public string Site { get; init; } = string.Empty;

	/// <summary>For site <c>override</c>: <c>yes</c>, <c>no</c>, or empty (non-override).</summary>
	public string? OverrideKey { get; init; }

	/// <summary>Accepted row dataset tier.</summary>
	public string AcceptedTier { get; init; } = string.Empty;

	/// <summary>Key (expected) row dataset tier.</summary>
	public string KeyTier { get; init; } = string.Empty;

	/// <summary>Combined FoodState mask of the accepted row (state + satisfiers).</summary>
	public string AcceptedState { get; init; } = string.Empty;

	/// <summary>Combined FoodState mask of the key row.</summary>
	public string KeyState { get; init; } = string.Empty;

	/// <summary>The atom's parsedName (verbatim from the trace).</summary>
	public string ParsedName { get; init; } = string.Empty;

	/// <summary>Key head phrase (leading non-state tokens of the key description, singularized).</summary>
	public string KeyHead { get; init; } = string.Empty;

	/// <summary>First accepted description (sanitized).</summary>
	public string AcceptedDesc { get; init; } = string.Empty;

	/// <summary>First expected (key) description (sanitized).</summary>
	public string KeyDesc { get; init; } = string.Empty;

	/// <summary>The raw recipe line (sanitized).</summary>
	public string RawText { get; init; } = string.Empty;

	/// <summary>When relation is <c>other</c> and a missing field caused it: the field name.</summary>
	public string? MissingField { get; init; }

	/// <summary>When relation is <c>same-head-other-qualifier</c>: the qualifier diff (key-only, accepted-only).</summary>
	public (IReadOnlyList<string> KeyOnly, IReadOnlyList<string> AcceptedOnly)? QualifierDiff { get; init; }

	/// <summary>When relation is <c>row-choice-tier</c>: <c>key</c> or <c>accepted</c> indicating which tier is higher.</summary>
	public string? TierDirection { get; init; }
}

/// <summary>
/// Output writers for the census runner. Defaults resolve to <see cref="System.Console.Out"/>
/// and <see cref="System.Console.Error"/>. Tests inject <see cref="System.IO.StringWriter"/>
/// instances to capture the TSV and summary without touching the real console.
/// </summary>
public sealed record OutputWriters(
	System.IO.TextWriter Output,
	System.IO.TextWriter Error);
