namespace LetUsCook.AutoWrongCensus.Models;

/// <summary>
/// The census output row for one auto-wrong trace line.
/// Columns (TSV): holdoutId lineIndex set relation site overrideKey acceptedTier keyTier
/// acceptedState keyState parsedName keyHead acceptedDesc keyDesc rawText.
/// </summary>
public sealed record ClassificationResult
{
	/// <summary>Holdout id.</summary>
	public string HoldoutId { get; init; } = string.Empty;

	/// <summary>Line index.</summary>
	public int LineIndex { get; init; }

	/// <summary>Trace set.</summary>
	public string Set { get; init; } = string.Empty;

	/// <summary>Relation class: one of the eight defined in the brief §3.</summary>
	public string Relation { get; init; } = string.Empty;

	/// <summary>Decision site: reuse / ranker / override / curated.</summary>
	public string Site { get; init; } = string.Empty;

	/// <summary>Whether the normalized rawText is a key in <c>exact-overrides.json</c>; null when site is not <c>override</c>.</summary>
	public string? OverrideKey { get; init; }

	/// <summary>Accepted row dataset tier (empty when missing).</summary>
	public string AcceptedTier { get; init; } = string.Empty;

	/// <summary>Key row dataset tier (empty when missing).</summary>
	public string KeyTier { get; init; } = string.Empty;

	/// <summary>FoodState mask of the accepted row (state | satisfiers).</summary>
	public string AcceptedState { get; init; } = string.Empty;

	/// <summary>FoodState mask of the key row (state | satisfiers).</summary>
	public string KeyState { get; init; } = string.Empty;

	/// <summary>The atom's parsed name (verbatim).</summary>
	public string ParsedName { get; init; } = string.Empty;

	/// <summary>Key head phrase: the production-normalized, singularized, state-truncated head of the key description.</summary>
	public string KeyHead { get; init; } = string.Empty;

	/// <summary>Key description (first expected description).</summary>
	public string KeyDesc { get; init; } = string.Empty;

	/// <summary>Accepted description (first actual description).</summary>
	public string AcceptedDesc { get; init; } = string.Empty;

	/// <summary>Raw text from the trace.</summary>
	public string RawText { get; init; } = string.Empty;

	/// <summary>When the relation is <c>other</c>, the name of the missing field that prevented a higher-priority classification.</summary>
	public string MissingField { get; init; } = string.Empty;

	/// <summary>Qualifier tokens in the key description (non-state), for the <c>same-head-other-qualifier</c> relation.</summary>
	public IReadOnlyList<string> KeyQualifiers { get; init; } = [];

	/// <summary>Qualifier tokens in the accepted description (non-state), for the <c>same-head-other-qualifier</c> relation.</summary>
	public IReadOnlyList<string> AcceptedQualifiers { get; init; } = [];

	/// <summary>Direction of the tier difference: <c>keyHigher</c> or <c>acceptedHigher</c>; empty when not row-choice-tier.</summary>
	public string TierDirection { get; init; } = string.Empty;
}
