{"content":"using LetUsCook.Fdc;
using LetUsCook.Fdc.Classification;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.RegularExpressions;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies every auto-wrong trace line by accepted-row vs key-row relation and decision site
/// using production helpers only (D-014).
/// </summary>
public sealed partial class AutoWrongClassifier
{
	/// <summary>Relation classes.</summary>
	public const string NoLabel = "no-label";
	public const string PackUnitState = "pack-unit-state";
	public const string CompoundHeadLost = "compound-head-lost";
	public const string StateMismatch = "state-mismatch";
	public const string RowChoiceTier = "row-choice-tier";
	public const string SameHeadOtherQualifier = "same-head-other-qualifier";
	public const string SiblingFood = "sibling-food";
	public const string Other = "other";

	/// <summary>Site classes.</summary>
	public const string Reuse = "reuse";
	public const string Ranker = "ranker";
	public const string Override = "override";
	public const string Curated = "curated";

	// F-428 P12.13: can/jar unit detection — the production matcher's own state parsing
	// (FdcNormalizer.NormalizeToTokens) drops the unit word, so we must detect it in the raw text.
	// The regex is a production-conservative word-boundary match; the census counts it as a
	// pack-unit-state signal. (D-014: the unit check is data hygiene, not matcher logic.)
	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();

	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;

	/// <summary>Reusable single-token list to avoid CA1861 (constant-array) per-token calls.</summary>
	private readonly List<string> _singleToken = new(1);

	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		ArgumentNullException.ThrowIfNull(normalizer);
		ArgumentNullException.ThrowIfNull(overrideKeys);
		_normalizer = normalizer;
		_overrideKeys = overrideKeys;
	}

	/// <summary>
	/// Classifies one trace line. Only auto-wrong lines (auto==true, correct==false) are
	/// meaningful; non-auto lines are silently skipped (returns <c>default</c>).
	/// </summary>
	/// <param name="line">One HoldoutGate trace line.</param>
	/// <returns>The classification, or <c>default</c> when the line is not auto-wrong.</returns>
	public ClassificationResult? Classify(TraceLine line)
	{
		if (!line.Auto || line.Correct)
		{
			return null;
		}

		var atom = GetAcceptedAtom(line);
		if (atom is null)
		{
			return null;
		}

		var keyDesc = line.ExpectedDescriptions.FirstOrDefault() ?? string.Empty;
		var accDesc = line.ActualDescriptions.FirstOrDefault() ?? string.Empty;
		var keyType = line.ExpectedDataTypes.FirstOrDefault() ?? string.Empty;
		var accType = line.ActualDataTypes.FirstOrDefault() ?? string.Empty;

		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var accTokens = accDesc.Length > 0 ? _normalizer.NormalizeToTokens(accDesc) : [];
		var keyState = CombinedState(keyTokens);
		var accState = CombinedState(accTokens);

		var keyHeadParsed = keyDesc.Length > 0 ? FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyType)) : default;
		var accHeadParsed = accDesc.Length > 0 ? FdcDescriptionParser.Parse(accDesc, DatasetOf(accType)) : default;

		var headKey = SingularPhrase(keyHeadParsed.HeadTerm);
		var headAcc = accDesc.Length > 0 ? SingularPhrase(accHeadParsed.HeadTerm) : [];
		var parsedNorm = SingularPhrase(atom.ParsedName);

		var keyPhrase = KeyHeadPhrase(keyTokens);
		var keyQualifiers = SingularPhrase(keyHeadParsed.Qualifiers);
		var accQualifiers = accDesc.Length > 0 ? SingularPhrase(accHeadParsed.Qualifiers) : [];

		var site = ResolveSite(atom.Path, atom.Reused);

		var result = new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			Relation = Other,
			Site = site,
			OverrideKey = site == Override ? (IsOverrideKey(atom.RawText) ? "yes" : "no") : string.Empty,
			AcceptedTier = accType,
			KeyTier = keyType,
			AcceptedState = accState.ToString(),
			KeyState = keyState.ToString(),
			ParsedName = atom.ParsedName,
			KeyHead = string.Join(' ', keyPhrase),
			AcceptedDesc = accDesc,
			KeyDesc = keyDesc,
			RawText = line.RawText,
		};

		// Rule 1: no-label — expected description empty.
		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			result.Relation = NoLabel;
			return result;
		}

		// Rule 2: pack-unit-state — rawText has a can/jar unit; key has Canned; accepted does not.
		if (PackUnitRegex().IsMatch(line.RawText)
			&& (keyState & FoodState.Canned) != 0
			&& (accState & FoodState.Canned) == 0)
		{
			result.Relation = PackUnitState;
			return result;
		}

		// Rule 3: compound-head-lost — key head phrase 2+ words, parsedName equals only its first word.
		if (keyPhrase.Count >= 2 && parsedNorm.Count >= 1 && parsedNorm.SequenceEqual([IngredientLineResolver.SingularizeToken(keyPhrase[0])], StringComparer.OrdinalIgnoreCase))
		{
			result.Relation = CompoundHeadLost;
			return result;
		}

		// Rule 4: state-mismatch — HeadTerms agree, FoodState masks differ.
		if (HeadsAgree(headKey, headAcc))
		{
			if (keyState != accState)
			{
				result.Relation = StateMismatch;
				return result;
			}

			// Rule 5: row-choice-tier — dataType differs.
			if (keyType.Length > 0 && accType.Length > 0 && keyType != accType)
			{
				result.Relation = RowChoiceTier;
				return result;
			}

			// Missing dataType on either side → other (missingField).
			if (keyType.Length == 0 || accType.Length == 0)
			{
				result.MissingField = keyType.Length == 0 ? "expectedDataTypes" : "actualDataTypes";
				result.Relation = Other;
				return result;
			}

			// Rule 6: same-head-other-qualifier — heads agree, state agrees, types equal.
			if (keyQualifiers.SequenceEqual(accQualifiers, StringComparer.OrdinalIgnoreCase))
			{
				// Identical qualifiers — still same-head-other-qualifier (duplicate row).
			}

			result.KeyOnlyQualifiers = keyQualifiers.Except(accQualifiers, StringComparer.OrdinalIgnoreCase).ToList();
			result.AcceptedOnlyQualifiers = accQualifiers.Except(keyQualifiers, StringComparer.OrdinalIgnoreCase).ToList();
			result.Relation = SameHeadOtherQualifier;
			return result;
		}

		// Rule 7: sibling-food — HeadTerms differ.
		if (accDesc.Length == 0)
		{
			result.MissingField = "actualDescriptions";
			result.Relation = Other;
			return result;
		}

		result.Relation = SiblingFood;
		return result;
	}

	/// <summary>
	/// Computes the key head phrase: tokens of the key description up to the first token that
	/// production considers a state or modifier word. Uses the production lexicon (FdcLexicon)
	/// and production state helpers (D-014).
	/// </summary>
	/// <param name="tokens">Normalized tokens of the key description.</param>
	/// <returns>The head phrase tokens (possibly empty).</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> tokens)
	{
		var phrase = new List<string>(tokens.Count);
		var lex = FdcLexicon.Default;

		foreach (var tok in tokens)
		{
			if (IsStateWord(tok, lex))
			{
				return phrase;
			}

			phrase.Add(tok);
		}

		return phrase;
	}

	/// <summary>Combines production's state and satisfier masks for a token list.</summary>
	internal static FoodState CombinedState(IReadOnlyList<string> tokens)
		=> FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	/// <summary>
	/// Normalizes a text string to tokens and singularizes each (D-014: uses production
	/// <see cref="FdcNormalizer"/> and <see cref="IngredientLineResolver.SingularizeToken"/>).
	/// </summary>
	private IReadOnlyList<string> SingularPhrase(string? text)
		=> _normalizer.NormalizeToTokens(text).Select(IngredientLineResolver.SingularizeToken).ToArray();

	private static bool HeadsAgree(IReadOnlyList<string> key, IReadOnlyList<string> acc)
		=> key.SequenceEqual(acc, StringComparer.OrdinalIgnoreCase);

	private static FdcDataset DatasetOf(string? dataType)
		=> Enum.TryParse(dataType, ignoreCase: true, out FdcDataset ds) ? ds : FdcDataset.None;

	private TraceAtom? GetAcceptedAtom(TraceLine line)
	{
		foreach (var atom in line.Atoms)
		{
			if (atom.Outcome == "accepted")
			{
				return atom;
			}
		}

		return line.Atoms.FirstOrDefault();
	}

	private string ResolveSite(string path, bool reused) => path switch
	{
		"override" => Override,
		"curated" => Curated,
		"ranker" when reused => Reuse,
		"ranker" => Ranker,
		_ => string.Empty, // unknown path → empty site, runner counts and exits 1
	};

	private static bool IsStateWord(string token, FdcLexicon lex)
	{
		// Production lexicon: words that USDA considers state/modifier qualifiers.
		if (lex.ModifierWords.Contains(token) || lex.PreparationStates.Contains(token))
		{
			return true;
		}

		// Single-token state extraction (D-014: uses production helpers).
		_singleToken.Clear();
		_singleToken.Add(token);
		if (FdcMatcher.ExtractCandidateState(_singleToken) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_singleToken) != FoodState.None)
		{
			return true;
		}

		return false;
	}

	/// <summary>
	/// Checks whether the raw text (stripped of parenthesized content and lowercased) is
	/// a key in <c>exact-overrides.json</c>. The file is loaded from the production assembly
	/// embedded resources (not a copy of matcher logic — the brief explicitly names the file).
	/// </summary>
	private bool IsOverrideKey(string rawText)
	{
		var normalized = StripParen(rawText.Trim()).ToLowerInvariant();
		return _overrideKeys.Contains(normalized) || _overrideKeys.Contains(rawText.Trim().ToLowerInvariant());
	}

	private static string StripParen(string text)
	{
		var index = text.IndexOf('(', StringComparison.Ordinal);
		return index >= 0 ? text[..index] : text;
	}

	private static string Sanitize(string text)
		=> text.Replace('\t', ' ').Replace('\n', ' ').Replace('\r', ' ');

	private static int TierRank(string tier)
		=> tier switch
		{
			"Foundation" => 4, "SrLegacy" => 3, "Survey" => 2, "Branded" => 1, _ => 0,
		};
}
","path":"tools/LetUsCook.AutoWrongCensus/Services/AutoWrongClassifier.cs","i":"Writing the classifier"}

{"content":"using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

using LetUsCook.AutoWrongCensus.Models;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies one auto-wrong trace line by accepted-row vs key-row relation and decision site.
/// Calls the production helpers listed in the brief (§4): <see cref="FdcNormalizer.NormalizeToTokens"/>,
/// <see cref="FdcMatcher.ExtractCandidateState"/>, <see cref="FdcMatcher.ExtractCandidateSatisfiers"/>,
/// <see cref="FdcDescriptionParser.Parse"/>, <see cref="IngredientLineResolver.SingularizeToken"/>,
/// and <see cref="IngredientLineResolver.ShouldReuse"/>.
/// </summary>
public sealed partial class AutoWrongClassifier
{
	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;

	/// <summary>Single-token reusable list to avoid per-token allocations (CA1861).</summary>
	private readonly List<string> _singleToken = new(1);

	/// <summary>
	/// <c>can|cans|jar|jars</c> as a word boundary — the unit marker for pack-unit-state.
	/// </summary>
	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();

	/// <summary>
	/// Creates a classifier using the production normalizer and the embedded override key index.
	/// </summary>
	/// <param name="normalizer">The production FDC normalizer.</param>
	/// <param name="overrideKeys">The embedded <c>exact-overrides.json</c> key index.</param>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		ArgumentNullException.ThrowIfNull(normalizer);
		ArgumentNullException.ThrowIfNull(overrideKeys);
		_normalizer = normalizer;
		_overrideKeys = overrideKeys;
	}

	/// <summary>
	/// Classifies one auto-wrong trace line. Only lines with <c>auto == true && correct == false</c>
	/// are meaningful; the caller filters.
	/// </summary>
	/// <param name="line">The trace line.</param>
	/// <param name="atom">The atom to classify (use the first accepted atom, or atoms[0]).</param>
	/// <returns>The classification result.</returns>
	public ClassificationResult Classify(TraceLine line, TraceAtom atom)
	{
		ArgumentNullException.ThrowIfNull(line);
		ArgumentNullException.ThrowIfNull(atom);

		var keyDesc = line.ExpectedDescriptions.FirstOrDefault();
		var accDesc = line.ActualDescriptions.FirstOrDefault();
		var keyType = line.ExpectedDataTypes.FirstOrDefault();
		var accType = line.ActualDataTypes.FirstOrDefault();

		// no-label: expected (key) description empty
		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			return new ClassificationResult
			{
				HoldoutId = line.HoldoutId,
				LineIndex = line.LineIndex,
				Set = line.Set,
				Relation = "no-label",
				Site = ComputeSite(atom, line),
				OverrideKey = string.Empty,
				AcceptedTier = accType,
				KeyTier = string.Empty,
				AcceptedState = ComputeState(accDesc),
				KeyState = string.Empty,
				ParsedName = atom.ParsedName,
				KeyHead = string.Empty,
				AcceptedDesc = accDesc ?? string.Empty,
				KeyDesc = string.Empty,
				RawText = line.RawText,
			};
		}

		// Missing accepted description: classify as other with missing field
		if (string.IsNullOrWhiteSpace(accDesc))
		{
			return new ClassificationResult
			{
				HoldoutId = line.HoldoutId,
				LineIndex = line.LineIndex,
				Set = line.Set,
				Relation = "other",
				Site = ComputeSite(atom, line),
				OverrideKey = string.Empty,
				AcceptedTier = string.Empty,
				KeyTier = keyType,
				AcceptedState = string.Empty,
				KeyState = ComputeState(keyDesc),
				ParsedName = atom.ParsedName,
				KeyHead = ComputeKeyHead(keyDesc, keyType),
				AcceptedDesc = string.Empty,
				KeyDesc = keyDesc,
				RawText = line.RawText,
				MissingField = "actualDescriptions",
			};
		}

		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var accTokens = _normalizer.NormalizeToTokens(accDesc);
		var keyState = CombinedState(keyTokens);
		var accState = CombinedState(accTokens);

		var keyHeadParsed = FdcDescriptionParser.Parse(keyDesc, DatasetOf(keyType));
		var accHeadParsed = string.IsNullOrWhiteSpace(accDesc) ? new ParsedFdcDescription(string.Empty, [], null)
			: FdcDescriptionParser.Parse(accDesc, DatasetOf(accType));

		var keyHead = SingularPhrase(keyHeadParsed.HeadTerm);
		var accHead = accDesc is null ? [] : SingularPhrase(accHeadParsed.HeadTerm);

		var keyPhrase = KeyHeadPhrase(keyTokens);
		var parsedTokens = _normalizer.NormalizeToTokens(atom.ParsedName)
			.Select(IngredientLineResolver.SingularizeToken).ToArray();

		// Rule 2: pack-unit-state
		if (PackUnitRegex().IsMatch(line.RawText)
			&& (keyState & FoodState.Canned) != 0
			&& (accState & FoodState.Canned) == 0)
		{
			return new ClassificationResult
			{
				HoldoutId = line.HoldoutId,
				LineIndex = line.LineIndex,
				Set = line.Set,
				Relation = "pack-unit-state",
				Site = ComputeSite(atom, line),
				OverrideKey = string.Empty,
				AcceptedTier = accType,
				KeyTier = keyType,
				AcceptedState = accState.ToString(),
				KeyState = keyState.ToString(),
				ParsedName = atom.ParsedName,
				KeyHead = ComputeKeyHead(keyDesc, keyType),
				AcceptedDesc = accDesc,
				KeyDesc = keyDesc,
				RawText = line.RawText,
			};
		}

		// Rule 3: compound-head-lost
		if (keyPhrase.Count >= 2
			&& parsedTokens.Length >= 1
			&& parsedTokens.Length == 1
			&& string.Equals(parsedTokens[0], IngredientLineResolver.SingularizeToken(keyPhrase[0]), StringComparison.OrdinalIgnoreCase))
		{
			return new ClassificationResult
			{
				HoldoutId = line.HoldoutId,
				LineIndex = line.LineIndex,
				Set = line.Set,
				Relation = "compound-head-lost",
				Site = ComputeSite(atom, line),
				OverrideKey = ComputeOverrideKey(line),
				AcceptedTier = accType,
				KeyTier = keyType,
				AcceptedState = accState.ToString(),
				KeyState = keyState.ToString(),
				ParsedName = atom.ParsedName,
				KeyHead = string.Join(' ', keyPhrase),
				AcceptedDesc = accDesc,
				KeyDesc = keyDesc,
				RawText = line.RawText,
			};
		}

		// Rule 4: state-mismatch
		if (HeadsAgree(keyHead, accHead) && keyState != accState)
		{
			return new ClassificationResult
			{
				HoldoutId = line.HoldoutId,
				LineIndex = line.LineIndex,
				Set = line.Set,
				Relation = "state-mismatch",
				Site = ComputeSite(atom, line),
				OverrideKey = ComputeOverrideKey(line),
				AcceptedTier = accType,
				KeyTier = keyType,
				AcceptedState = accState.ToString(),
				KeyState = keyState.ToString(),
				ParsedName = atom.ParsedName,
				KeyHead = string.Join(' ', keyPhrase),
				AcceptedDesc = accDesc,
				KeyDesc = keyDesc,
				RawText = line.RawText,
			};
		}

		// Rule 5: row-choice-tier (requires both types)
		if (HeadsAgree(keyHead, accHead)
			&& keyState == accState
			&& !string.IsNullOrEmpty(keyType)
			&& !string.IsNullOrEmpty(accType)
			&& keyType != accType)
		{
			return new ClassificationResult
			{
				HoldoutId = line.HoldoutId,
				LineIndex = line.LineIndex,
				Set = line.Set,
				Relation = "row-choice-tier",
				Site = ComputeSite(atom, line),
				OverrideKey = ComputeOverrideKey(line),
				AcceptedTier = accType,
				KeyTier = keyType,
				AcceptedState = accState.ToString(),
				KeyState = keyState.ToString(),
				ParsedName = atom.ParsedName,
				KeyHead = string.Join(' ', keyPhrase),
				AcceptedDesc = accDesc,
				KeyDesc = keyDesc,
				RawText = line.RawText,
			};
		}

		// Missing dataType: classify as other
		if (HeadsAgree(keyHead, accHead) && keyState == accState)
		{
			if (string.IsNullOrEmpty(keyType) || string.IsNullOrEmpty(accType))
			{
				return new ClassificationResult
				{
					HoldoutId = line.HoldoutId,
					LineIndex = line.LineIndex,
					Set = line.Set,
					Relation = "other",
					Site = ComputeSite(atom, line),
					OverrideKey = ComputeOverrideKey(line),
					AcceptedTier = accType,
					KeyTier = keyType,
					AcceptedState = accState.ToString(),
					KeyState = keyState.ToString(),
					ParsedName = atom.ParsedName,
					KeyHead = string.Join(' ', keyPhrase),
					AcceptedDesc = accDesc,
					KeyDesc = keyDesc,
					RawText = line.RawText,
					MissingField = string.IsNullOrEmpty(keyType) ? "expectedDataTypes" : "actualDataTypes",
				};
			}

			// Rule 6: same-head-other-qualifier
			var keyQualifiers = SingularPhraseList(keyHeadParsed.Qualifiers);
			var accQualifiers = SingularPhraseList(accHeadParsed.Qualifiers);
			var keySet = new HashSet<string>(keyQualifiers, StringComparer.OrdinalIgnoreCase);
			var accSet = new HashSet<string>(accQualifiers, StringComparer.OrdinalIgnoreCase);
			var keyOnly = keySet.Where(t => !accSet.Contains(t)).ToList();
			var accOnly = accSet.Where(t => !keySet.Contains(t)).ToList();
			return new ClassificationResult
			{
				HoldoutId = line.HoldoutId,
				LineIndex = line.LineIndex,
				Set = line.Set,
				Relation = "same-head-other-qualifier",
				Site = ComputeSite(atom, line),
				OverrideKey = ComputeOverrideKey(line),
				AcceptedTier = accType,
				KeyTier = keyType,
				AcceptedState = accState.ToString(),
				KeyState = keyState.ToString(),
				ParsedName = atom.ParsedName,
				KeyHead = string.Join(' ', keyPhrase),
				AcceptedDesc = accDesc,
				KeyDesc = keyDesc,
				RawText = line.RawText,
				KeyOnlyQualifiers = keyOnly.Count > 0 ? (IReadOnlyList<string>)keyOnly : null,
				AcceptedOnlyQualifiers = accOnly.Count > 0 ? (IReadOnlyList<string>)accOnly : null,
			};
		}

		// Rule 7: sibling-food (heads differ)
		return new ClassificationResult
		{
			HoldoutId = line.HoldoutId,
			LineIndex = line.LineIndex,
			Set = line.Set,
			Relation = "sibling-food",
			Site = ComputeSite(atom, line),
			OverrideKey = ComputeOverrideKey(line),
			AcceptedTier = accType,
			KeyTier = keyType,
			AcceptedState = accState.ToString(),
			KeyState = keyState.ToString(),
			ParsedName = atom.ParsedName,
			KeyHead = string.Join(' ', keyPhrase),
			AcceptedDesc = accDesc,
			KeyDesc = keyDesc,
			RawText = line.RawText,
		};
	}

	// ── helpers ──────────────────────────────────────────────────────────────────────

	/// <summary>
	/// Computes the key head phrase: leading normalized tokens up to the first token that
	/// production considers a state word, modifier, or preparation state.
	/// </summary>
	internal IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> tokens)
	{
		var phrase = new List<string>(Math.Max(0, tokens.Count));
		foreach (var tok in tokens)
		{
			_singleToken[0] = tok;
			if (IsStateWord(tok))
			{
				return phrase;
			}
			phrase.Add(tok);
		}
		return phrase;
	}

	/// <summary>
	/// Returns <see langword="true"/> when <paramref name="token"/> is excluded from the head phrase
	/// by production lexicon or matcher rules.
	/// </summary>
	private static bool IsStateWord(string token)
	{
		var lex = FdcLexicon.Default;
		if (lex.ModifierWords.Contains(token))
		{
			return true;
		}
		_singleToken[0] = token;
		var state = FdcMatcher.ExtractCandidateState(_singleToken);
		if (state != FoodState.None)
		{
			return true;
		}
		var sat = FdcMatcher.ExtractCandidateSatisfiers(_singleToken);
		return sat != FoodState.None;
	}

	/// <summary>Combined state mask: state ∪ satisfiers (production's two-pass composition).</summary>
	internal static FoodState CombinedState(IReadOnlyList<string> tokens) =>
		FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	private static FoodDataset DatasetOf(string? type) => Enum.TryParse<FoodDataset>(type, out var ds) ? ds : FoodDataset.None;

	private static string ComputeState(string? desc) => desc is null ? string.Empty : CombinedState(FdcNormalizer.NormalizeToTokens(desc)).ToString();

	private static IReadOnlyList<string> SingularPhrase(string? text) =>
		text is null ? [] : FdcNormalizer.NormalizeToTokens(text).Select(IngredientLineResolver.SingularizeToken).ToArray();

	private static IReadOnlyList<string> SingularPhraseList(IReadOnlyList<string> tokens) =>
		tokens.Select(IngredientLineResolver.SingularizeToken).ToArray();

	private static bool HeadsAgree(IReadOnlyList<string> keyHead, IReadOnlyList<string> accHead) =>
		keyHead.SequenceEqual(accHead, StringComparer.OrdinalIgnoreCase);

	private static string ComputeSite(TraceAtom atom, TraceLine line)
	{
		var path = atom.Path;
		return path switch
		{
			"override" => "override",
			"curated" => "curated",
			"ranker" => atom.Reused ? "reuse" : "ranker",
			_ => string.Empty, // unknown path — runner will error
		};
	}

	private string ComputeOverrideKey(TraceLine line)
	{
		if (string.IsNullOrWhiteSpace(line.RawText))
		{
			return string.Empty;
		}
		var normalized = NormalizeForOverrideKey(line.RawText);
		return _overrideKeys.IsKey(normalized) ? "yes" : "no";
	}

	/// <summary>
	/// Normalizes raw text for <c>exact-overrides.json</c> lookup: lower-cased, trimmed,
	/// content from the first <c>(</c> dropped. This mirrors the production <c>MatchAsync</c>
	/// path's <c>StripFromParenthesis</c> logic (private in <c>FdcMatcher</c>), applied at the
	/// nearest reachable point — the census tool reads the file directly (data, not logic).
	/// </summary>
	private static string NormalizeForOverrideKey(string rawText)
	{
		var index = rawText.IndexOf('(');
		var text = index >= 0 ? rawText[..index] : rawText;
		return text.Trim().ToLowerInvariant();
	}

	/// <summary>
	/// For reuse-site lines, returns the number of auto-wrong lines where the production
	/// <c>ShouldReuse</c> rule would reject the reuse of the linked master.
	/// </summary>
	internal static int CountShouldReuseFalse(IEnumerable<TraceLine> lines, IEnumerable<TraceAtom> atoms)
	{
		var count = 0;
		foreach (var line in lines)
		{
			foreach (var atom in atoms)
			{
				if (atom.Path == "ranker" && atom.Reused && !string.IsNullOrWhiteSpace(atom.LinkedIngredientId))
				{
					var slug = IngredientLineParser.ComputeSlug(atom.ParsedName);
					if (!IngredientLineResolver.ShouldReuse(slug, atom.LinkedIngredientId))
					{
						count++;
					}
				}
			}
		}
		return count;
	}

	/// <summary>
	/// Sanitizes a string for TSV: replaces tabs, newlines, and carriage returns with spaces.
	/// </summary>
	internal static string SanitizeForTsv(string text) => text.Replace("\t", " ").Replace("\n", " ").Replace("\r", " ");
}
