{"content":"using System.Text.RegularExpressions;

using LetUsCook.Fdc;
using LetUsCook.Fdc.Lexicon;
using LetUsCook.Fdc.Matching;
using LetUsCook.Fdc.Parsing;
using LetUsCook.Fdc.Resolver;

using LetUsCook.AutoWrongCensus.Models;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>
/// Classifies one auto-wrong trace line by the accepted-row vs key-row relation (pack-unit-state,
/// compound-head-lost, state-mismatch, row-choice-tier, same-head-other-qualifier, sibling-food,
/// no-label, other) and the decision site (reuse, ranker, override, curated).
/// </summary>
/// <remarks>
/// Not thread-safe: the <c>_scratch</c> buffer is reused per call. The census runner calls
/// sequentially, so this is safe in production.
/// </remarks>
public sealed partial class AutoWrongClassifier
{
	[GeneratedRegex(@"\b(?:cans?|jars?)\b", RegexOptions.IgnoreCase)]
	private static partial Regex PackUnitRegex();

	private readonly FdcNormalizer _normalizer;
	private readonly ExactOverrideKeyIndex _overrideKeys;

	/// <summary>Scratch buffer for per-token state checks — avoids allocation.</summary>
	private readonly string?[] _scratch = new string[1];

	/// <summary>
	/// Creates a classifier that uses the production normalizer and the embedded
	/// <c>exact-overrides.json</c> key set.
	/// </summary>
	/// <param name="normalizer">The production <see cref="FdcNormalizer"/>.</param>
	/// <param name="overrideKeys">The embedded override key index.</param>
	public AutoWrongClassifier(FdcNormalizer normalizer, ExactOverrideKeyIndex overrideKeys)
	{
		ArgumentNullException.ThrowIfNull(normalizer);
		ArgumentNullException.ThrowIfNull(overrideKeys);
		_normalizer = normalizer;
		_overrideKeys = overrideKeys;
	}

	/// <summary>
	/// Classifies an auto-wrong trace line. Returns <c>null</c> when the atom path is unknown
	/// (the runner treats this as a fatal instrument error and exits 1).
	/// </summary>
	/// <param name="line">A trace line with <c>auto == true</c> and <c>correct == false</c>.</param>
	/// <param name="atom">The atom selected for classification (first accepted, or <c>atoms[0]</c>).</param>
	/// <returns>A <see cref="ClassificationResult"/> describing the relation and site.</returns>
	public ClassificationResult Classify(TraceLine line, TraceAtom atom)
	{
		var keyDesc = line.ExpectedDescriptions.FirstOrDefault();
		var accDesc = line.ActualDescriptions.FirstOrDefault();
		var keyType = line.ExpectedDataTypes.FirstOrDefault();
		var accType = line.ActualDataTypes.FirstOrDefault();

		// no-label: key (expected) description empty.
		if (string.IsNullOrWhiteSpace(keyDesc))
		{
			return new ClassificationResult
			{
				HoldoutId = line.HoldoutId,
				LineIndex = line.LineIndex,
				Set = line.Set,
				Relation = "no-label",
				Site = DetermineSite(atom),
				OverrideKey = string.Empty,
				AcceptedTier = accType,
				KeyTier = string.Empty,
				AcceptedState = ComputeStateMask(accDesc),
				KeyState = string.Empty,
				ParsedName = atom.ParsedName,
				KeyHead = string.Empty,
				AcceptedDesc = accDesc ?? string.Empty,
				KeyDesc = string.Empty,
				RawText = line.RawText,
				MissingField = null,
			};
		}

		var keyTokens = _normalizer.NormalizeToTokens(keyDesc);
		var accTokens = accDesc is null ? [] : _normalizer.NormalizeToTokens(accDesc);
		var keyState = CombinedState(keyTokens);
		var accState = CombinedState(accTokens);
		var keyHeadParsed = ParseKeyHead(keyDesc, keyType);
		var headKey = SingularPhrase(keyHeadParsed.HeadTerm);
		var headAcc = accDesc is null ? [] : SingularPhrase(ParseKeyHead(accDesc, accType).HeadTerm);
		var parsedNorm = SingularPhrase(atom.ParsedName);
		var keyPhrase = KeyHeadPhrase(keyTokens);
		var site = DetermineSite(atom);
		var overrideKey = site == "override" && atom.Path == "override" ? ComputeOverrideKey(line.RawText) : string.Empty;
		var missingField = (string?)null;

		// Relation: rule 2 — pack-unit-state
		if (PackUnitRegex.IsMatch(line.RawText) && (keyState & FoodState.Canned) != 0 && (accState & FoodState.Canned) == 0)
		{
			return new ClassificationResult
			{
				HoldoutId = line.HoldoutId, LineIndex = line.LineIndex, Set = line.Set,
				Relation = "pack-unit-state", Site = site, OverrideKey = overrideKey,
				AcceptedTier = accType, KeyTier = keyType,
				AcceptedState = FormatState(accState), KeyState = FormatState(keyState),
				ParsedName = atom.ParsedName, KeyHead = string.Join(" ", keyPhrase),
				AcceptedDesc = accDesc ?? string.Empty, KeyDesc = keyDesc, RawText = line.RawText,
			};
		}

		// Relation: rule 3 — compound-head-lost
		if (keyPhrase.Count >= 2 && parsedNorm.Count >= 1 && parsedNorm.Count == 1
			&& string.Equals(parsedNorm[0], IngredientLineResolver.SingularizeToken(keyPhrase[0]), StringComparison.OrdinalIgnoreCase))
		{
			return new ClassificationResult
			{
				HoldoutId = line.HoldoutId, LineIndex = line.LineIndex, Set = line.Set,
				Relation = "compound-head-lost", Site = site, OverrideKey = overrideKey,
				AcceptedTier = accType, KeyTier = keyType,
				AcceptedState = FormatState(accState), KeyState = FormatState(keyState),
				ParsedName = atom.ParsedName, KeyHead = string.Join(" ", keyPhrase),
				AcceptedDesc = accDesc ?? string.Empty, KeyDesc = keyDesc, RawText = line.RawText,
			};
		}

		// If the accepted row is missing, classify as other.
		if (accDesc is null || accDesc.Length == 0)
		{
			return new ClassificationResult
			{
				HoldoutId = line.HoldoutId, LineIndex = line.LineIndex, Set = line.Set,
				Relation = "other", Site = site, OverrideKey = overrideKey,
				AcceptedTier = accType, KeyTier = keyType,
				AcceptedState = FormatState(accState), KeyState = FormatState(keyState),
				ParsedName = atom.ParsedName, KeyHead = string.Join(" ", keyPhrase),
				AcceptedDesc = string.Empty, KeyDesc = keyDesc, RawText = line.RawText,
				MissingField = "actualDescriptions",
			};
		}

		// Head agreement (used by rules 4-7).
		var headsAgree = headKey.SequenceEqual(headAcc, StringComparer.OrdinalIgnoreCase);

		// Relation: rule 4 — state-mismatch
		if (headsAgree && keyState != accState)
		{
			return new ClassificationResult
			{
				HoldoutId = line.HoldoutId, LineIndex = line.LineIndex, Set = line.Set,
				Relation = "state-mismatch", Site = site, OverrideKey = overrideKey,
				AcceptedTier = accType, KeyTier = keyType,
				AcceptedState = FormatState(accState), KeyState = FormatState(keyState),
				ParsedName = atom.ParsedName, KeyHead = string.Join(" ", keyPhrase),
				AcceptedDesc = accDesc, KeyDesc = keyDesc, RawText = line.RawText,
			};
		}

		// Relation: rule 5 — row-choice-tier
		if (headsAgree && keyState == accState)
		{
			if (keyType.Length > 0 && accType.Length > 0 && keyType != accType)
			{
				return new ClassificationResult
				{
					HoldoutId = line.HoldoutId, LineIndex = line.LineIndex, Set = line.Set,
					Relation = "row-choice-tier", Site = site, OverrideKey = overrideKey,
					AcceptedTier = accType, KeyTier = keyType,
					AcceptedState = FormatState(accState), KeyState = FormatState(keyState),
					ParsedName = atom.ParsedName, KeyHead = string.Join(" ", keyPhrase),
					AcceptedDesc = accDesc, KeyDesc = keyDesc, RawText = line.RawText,
				};
			}

			// Missing dataType: other.
			if (keyType.Length == 0)
			{
				return new ClassificationResult
				{
					HoldoutId = line.HoldoutId, LineIndex = line.LineIndex, Set = line.Set,
					Relation = "other", Site = site, OverrideKey = overrideKey,
					AcceptedTier = accType, KeyTier = keyType,
					AcceptedState = FormatState(accState), KeyState = FormatState(keyState),
					ParsedName = atom.ParsedName, KeyHead = string.Join(" ", keyPhrase),
					AcceptedDesc = accDesc, KeyDesc = keyDesc, RawText = line.RawText,
					MissingField = "expectedDataTypes",
				};
			}

			// Relation: rule 6 — same-head-other-qualifier
			var keyQual = SingularPhrase(keyHeadParsed.Qualifiers);
			var accQual = SingularPhrase(ParseKeyHead(accDesc, accType).Qualifiers);
			var keyQualSet = new HashSet<string>(keyQual, StringComparer.OrdinalIgnoreCase);
			var accQualSet = new HashSet<string>(accQual, StringComparer.OrdinalIgnoreCase);
			var keyOnly = keyQualSet.Except(accQualSet).OrderBy(t => t).ToArray();
			var accOnly = accQualSet.Except(keyQualSet).OrderBy(t => t).ToArray();

			return new ClassificationResult
			{
				HoldoutId = line.HoldoutId, LineIndex = line.LineIndex, Set = line.Set,
				Relation = "same-head-other-qualifier", Site = site, OverrideKey = overrideKey,
				AcceptedTier = accType, KeyTier = keyType,
				AcceptedState = FormatState(accState), KeyState = FormatState(keyState),
				ParsedName = atom.ParsedName, KeyHead = string.Join(" ", keyPhrase),
				AcceptedDesc = accDesc, KeyDesc = keyDesc, RawText = line.RawText,
				KeyOnlyQualifiers = keyOnly,
				AcceptedOnlyQualifiers = accOnly,
			};
		}

		// Relation: rule 7 — sibling-food (head terms differ).
		return new ClassificationResult
		{
			HoldoutId = line.HoldoutId, LineIndex = line.LineIndex, Set = line.Set,
			Relation = "sibling-food", Site = site, OverrideKey = overrideKey,
			AcceptedTier = accType, KeyTier = keyType,
			AcceptedState = FormatState(accState), KeyState = FormatState(keyState),
			ParsedName = atom.ParsedName, KeyHead = string.Join(" ", keyPhrase),
			AcceptedDesc = accDesc, KeyDesc = keyDesc, RawText = line.RawText,
		};
	}

	/// <summary>
	/// Extracts the head phrase from a token list: tokens up to (but not including) the first
	/// token that production classifies as a state word, modifier, or preparation state.
	/// </summary>
	/// <param name="tokens">Normalized tokens from the key description.</param>
	/// <returns>The head phrase tokens (may be empty).</returns>
	public IReadOnlyList<string> KeyHeadPhrase(IReadOnlyList<string> tokens)
	{
		var phrase = new List<string>();
		foreach (var token in tokens)
		{
			if (CarriesStateToken(token))
			{
				return phrase;
			}

			phrase.Add(token);
		}

		return phrase;
	}

	/// <summary>
	/// Determines whether a single token carries any production state semantics (state word,
	/// modifier word, or preparation state word).
	/// </summary>
	/// <param name="token">A single normalized token.</param>
	/// <returns>Whether the token carries state semantics.</returns>
	private bool CarriesStateToken(string token)
	{
		if (FdcLexicon.Default.ModifierWords.Contains(token))
		{
			return true;
		}

		_scratch[0] = token;
		return FdcMatcher.ExtractCandidateState(_scratch) != FoodState.None
			|| FdcMatcher.ExtractCandidateSatisfiers(_scratch) != FoodState.None;
	}

	/// <summary>Combines production state and satisfier masks for a token list.</summary>
	private static FoodState CombinedState(IReadOnlyList<string> tokens) =>
		FdcMatcher.ExtractCandidateState(tokens) | FdcMatcher.ExtractCandidateSatisfiers(tokens);

	/// <summary>Formats a FoodState mask for the TSV.</summary>
	private static string FormatState(FoodState state) => state == FoodState.None ? "None" : state.ToString();

	/// <summary>Singularizes a list of tokens via the production normalizer and resolver.</summary>
	private static IReadOnlyList<string> SingularPhrase(string? text) =>
		text is null ? [] : _normalizer.NormalizeToTokens(text).Select(IngredientLineResolver.SingularizeToken).ToArray();

	/// <summary>Parses a description into its head term and qualifiers.</summary>
	private static ParsedFdcDescription ParseKeyHead(string description, string dataType)
	{
		var dataset = Enum.TryParse<FdcDataset>(dataType, out var ds) ? ds : FdcDataset.None;
		return FdcDescriptionParser.Parse(description, dataset);
	}

	/// <summary>
	/// Determines the site from an atom: override/curated by path, ranker by reuse flag.
	/// Returns <c>null</c> for unknown paths (the runner exits 1).
	/// </summary>
	private string? DetermineSite(TraceAtom atom) => atom.Path switch
	{
		"override" => "override",
		"curated"  => "curated",
		"ranker"   => atom.Reused ? "reuse" : "ranker",
		_          => null,
	};

	/// <summary>
	/// Normalizes raw text for the <c>exact-overrides.json</c> key lookup: lower-cased, trimmed,
	/// content from the first <c>(</c> dropped (parity with production's <c>StripFromParenthesis</c>
	/// — the method is private in <c>FdcMatcher</c>; this is the closest public reproduction).
	/// </summary>
	private static string NormalizeForOverrideKey(string rawText)
	{
		var index = rawText.IndexOf('(', StringComparison.Ordinal);
		var text = index >= 0 ? rawText[..index] : rawText;
		return text.Trim().ToLowerInvariant();
	}

	/// <summary>Checks whether the normalized raw text is a key in <c>exact-overrides.json</c>.</summary>
	private static string ComputeOverrideKey(string rawText) =>
		_overrideKeys.IsKey(NormalizeForOverrideKey(rawText)) ? "yes" : "no";
}
