{"content":"using System.Text.Json;

using LetUsCook.AutoWrongCensus.Models;
using LetUsCook.AutoWrongCensus.Options;
using LetUsCook.Fdc;
using LetUsCook.Fdc.Resolver;
using Microsoft.Extensions.Options;

namespace LetUsCook.AutoWrongCensus.Services;

/// <summary>Runs one <c>census</c> or <c>pairs</c> invocation against a HoldoutGate trace.</summary>
public sealed class AutoWrongCensusRunner : IAutoWrongCensusRunner
{
	private static readonly JsonSerializerOptions JsonOptions = new(JsonSerializerDefaults.Web);

	private readonly AutoWrongClassifier _classifier;
	private readonly AutoWrongCensusOptions _options;
	private readonly TextWriter _output;
	private readonly TextWriter _error;

	/// <summary>Constructs the runner.</summary>
	/// <param name="classifier">The production classifier.</param>
	/// <param name="options">The bound CLI options.</param>
	/// <param name="output">TSV output writer; defaults to <see cref="System.Console.Out"/>.</param>
	/// <param name="error">Summary/diagnostics writer; defaults to <see cref="System.Console.Error"/>.</param>
	public AutoWrongCensusRunner(AutoWrongClassifier classifier, IOptions<AutoWrongCensusOptions> options, TextWriter output, TextWriter error)
	{
		ArgumentNullException.ThrowIfNull(classifier);
		ArgumentNullException.ThrowIfNull(options);
		ArgumentNullException.ThrowIfNull(output);
		ArgumentNullException.ThrowIfNull(error);
		_classifier = classifier;
		_options = options.Value;
		_output = output;
		_error = error;
	}

	/// <inheritdoc />
	public async Task<int> RunAsync(CancellationToken cancellationToken)
	{
		if (string.IsNullOrEmpty(_options.TracePath) || !File.Exists(_options.TracePath))
		{
			_error.WriteLine($"Error: trace file '{_options.TracePath}' not found.");
			return 1;
		}

		var records = await ReadTraceAsync(cancellationToken).ConfigureAwait(false);
		if (records == null)
		{
			return 1;
		}

		// D-029: refuse non-debug/batch sets.
		foreach (var r in records)
		{
			if (!r.Set.Equals("debug", StringComparison.OrdinalIgnoreCase) && !r.Set.Equals("batch", StringComparison.OrdinalIgnoreCase))
			{
				_error.WriteLine($"Error: refused set '{r.Set}' (only debug/batch accepted).");
				return 1;
			}
		}

		var autoWrong = records.Where(r => r.Auto && !r.Correct).ToList();

		switch (_options.Command.ToLowerInvariant())
		{
			case Options.CommandLineArgumentParser.CensusCommand:
				return await RunCensusAsync(autoWrong, cancellationToken).ConfigureAwait(false);
			case Options.CommandLineArgumentParser.PairsCommand:
				return await RunPairsAsync(cancellationToken).ConfigureAwait(false);
			default:
				_error.WriteLine("Error: unusable arguments. Usage: census <trace.jsonl> | pairs <census.tsv> <trace.jsonl>");
				return 1;
		}
	}

	private async Task<IReadOnlyList<TraceLine>?> ReadTraceAsync(CancellationToken cancellationToken)
	{
		await using var stream = File.OpenRead(_options.TracePath);
		var records = new List<TraceLine>();

		await foreach (var line in JsonDocument.ParseAsync(stream, cancellationToken: cancellationToken).ConfigureAwait(false))
		{
			records.Add(line.Deserialize<TraceLine>(JsonOptions) ?? new TraceLine());
		}

		return records;
	}

	private async Task<int> RunCensusAsync(IReadOnlyList<TraceLine> autoWrong, CancellationToken cancellationToken)
	{
		var header = "holdoutId\tlineIndex\tset\trelation\tsite\toverrideKey\tacceptedTier\tkeyTier\tacceptedState\tkeyState\tparsedName\tkeyHead\tacceptedDesc\tkeyDesc\trawText";
		_output.WriteLine(header);

		var results = new List<ClassificationResult>();
		var totalLines = autoWrong.Count;

		foreach (var line in autoWrong)
		{
			var result = _classifier.Classify(line);
			if (result.Site.Length == 0)
			{
				_error.WriteLine($"Error: unknown atom path '{line.Atoms[0].Path}' on {result.HoldoutId}#{result.LineIndex}; refusing.");
				return 1;
			}

			results.Add(result);
			_output.WriteLine(TsvRow(result));
		}

		WriteCensusSummary(totalLines, results);
		return 0;
	}

	private async Task<int> RunPairsAsync(CancellationToken cancellationToken)
	{
		if (string.IsNullOrEmpty(_options.CensusTsvPath) || !File.Exists(_options.CensusTsvPath))
		{
			_error.WriteLine($"Error: census TSV '{_options.CensusTsvPath}' not found.");
			return 1;
		}

		var censusRows = ReadCensusRows(_options.CensusTsvPath);
		var censusKeys = new HashSet<(string HoldoutId, int LineIndex)>(censusRows.Select(r => (r.HoldoutId, r.LineIndex)));

		// Re-read the trace (may be a different file from P12.7).
		var records = await ReadTraceAsync(cancellationToken).ConfigureAwait(false);
		if (records == null)
		{
			return 1;
		}

		// D-029: refuse non-debug/batch sets on the trace.
		foreach (var r in records)
		{
			if (!r.Set.Equals("debug", StringComparison.OrdinalIgnoreCase) && !r.Set.Equals("batch", StringComparison.OrdinalIgnoreCase))
			{
				_error.WriteLine($"Error: refused set '{r.Set}' (only debug/batch accepted).");
				return 1;
			}
		}

		var traceIndex = new Dictionary<(string HoldoutId, int LineIndex), TraceLine>(records.Count);
		foreach (var r in records)
		{
			traceIndex[(r.HoldoutId, r.LineIndex)] = r;
		}

		_output.WriteLine("holdoutId\tlineIndex\tparsedNameHead\tkeyHead\trawText");

		var matching = 0;
		var missing = 0;

		foreach (var row in censusRows)
		{
			if (row.Blocker != "window" || (row.Route != "compound" && row.Route != "other"))
			{
				continue;
			}

			if (traceIndex.TryGetValue((row.HoldoutId, row.LineIndex), out var trace))
			{
				matching++;
				var atom = trace.Atoms.Count > 0 ? trace.Atoms[0] : null;
				var parsedName = atom?.ParsedName ?? string.Empty;
				var parsedHead = FoldParsedName(parsedName);
				var keyHead = trace.ExpectedDescriptions.Count > 0
					? _classifier.KeyHeadPhrase(_classifier.Normalizer.NormalizeToTokens(trace.ExpectedDescriptions[0]))
					: [];
				_output.WriteLine($"{Sanitize(row.HoldoutId)}\t{row.LineIndex}\t{Sanitize(parsedHead)}\t{Sanitize(string.Join(' ', keyHead))}\t{Sanitize(trace.RawText)}");
			}
			else
			{
				missing++;
			}
		}

		if (missing > 0)
		{
			_error.WriteLine($"Warning: {missing} census window compound/other rows missing from the trace.");
		}

		_error.WriteLine($"pairs: {matching} window compound/other rows matched from {censusKeys.Count} total census rows.");
		return 0;
	}

	private IReadOnlyList<CensusRow> ReadCensusRows(string path)
	{
		var rows = new List<CensusRow>();
		var lines = File.ReadLines(path).ToList();
		if (lines.Count == 0)
		{
			return rows;
		}

		var header = lines[0].Split('\t');
		var indices = new Dictionary<string, int>();
		for (int i = 0; i < header.Length; i++)
		{
			indices[header[i]] = i;
		}

		for (int i = 1; i < lines.Count; i++)
		{
			var cols = lines[i].Split('\t');
			if (cols.Length < header.Length)
			{
				continue;
			}

			rows.Add(new CensusRow
			{
				HoldoutId = cols[indices["holdoutId"]],
				LineIndex = int.TryParse(cols[indices["lineIndex"]], out var li) ? li : -1,
				Blocker = cols[indices["blocker"]],
				Route = cols[indices["route"]],
			});
		}

		return rows;
	}

	private static string Sanitize(string value) => value.Replace('\t', ' ').Replace('\n', ' ').Replace('\r', ' ');

	private string FoldParsedName(string parsedName) =>
		string.Join(' ', Array.ConvertAll(
			_LetUsCook.Fdc.Lexicon.FdcLexicon.Default, parsedName.Split(' ', StringSplitOptions.RemoveEmptyEntries))
			.Select(t => LetUsCook.Fdc.Resolver.IngredientLineResolver.SingularizeToken(t.ToLowerInvariant())));

	private void WriteCensusSummary(int totalLines, IReadOnlyList<ClassificationResult> results)
	{
		var relationCounts = results.GroupBy(r => r.Relation).ToDictionary(g => g.Key, g => g.Count());
		var siteCounts = results.GroupBy(r => r.Site).ToDictionary(g => g.Key, g => g.Count());
		var relationSiteCounts = results.GroupBy(r => (r.Relation, r.Site)).ToDictionary(g => g.Key, g => g.Count());

		_error.WriteLine($"autoWrongCensus set={results[0].Set} traced={totalLines} autoWrong={totalLines}");
		_error.WriteLine("relation\tsite\tcount");

		var allRelations = relationCounts.Keys.Union(siteCounts.Keys).Union(
			results.Where(r => !string.IsNullOrEmpty(r.Relation)).Select(r => r.Relation))
			.Distinct().OrderBy(r => r).ToList();

		var allSites = siteCounts.Keys.Union(
			results.Where(r => !string.IsNullOrEmpty(r.Site)).Select(r => r.Site))
			.Distinct().OrderBy(s => s).ToList();

		foreach (var rel in allRelations)
		{
			foreach (var site in allSites)
			{
				var count = relationSiteCounts.GetValueOrDefault((rel, site), 0);
				if (count > 0)
				{
					_error.WriteLine($"{rel}\t{site}\t{count}");
				}
			}
		}

		// Other rate.
		var otherCount = relationCounts.GetValueOrDefault(AutoWrongClassifier.RelationOther, 0);
		_error.WriteLine($"other={otherCount}/{totalLines} ({otherCount * 100.0 / totalLines:F1}%)");

		// Missing fields.
		var missingFields = results.Where(r => !string.IsNullOrEmpty(r.MissingField)).GroupBy(r => r.MissingField).ToDictionary(g => g.Key, g => g.Count());
		if (missingFields.Count > 0)
		{
			_error.WriteLine("missingFields:");
			foreach (var (field, count) in missingFields)
			{
				_error.WriteLine($"  {field}: {count}");
			}
		}

		// Override key hits.
		var overrideLines = results.Where(r => r.Site == AutoWrongClassifier.SiteOverride).ToList();
		if (overrideLines.Count > 0)
		{
			var yesCount = overrideLines.Count(r => r.OverrideKey == "yes");
			_error.WriteLine($"overrideKey yes={yesCount} no={overrideLines.Count - yesCount}");
		}

		// ShouldReuse stats for reuse site.
		var reuseLines = results.Where(r => r.Site == AutoWrongClassifier.SiteReuse).ToList();
		if (reuseLines.Count > 0)
		{
			var falseCount = 0;
			foreach (var r in reuseLines)
			{
				var trace = results.FirstOrDefault(t => t.HoldoutId == r.HoldoutId && t.LineIndex == r.LineIndex);
				// We don't have the original trace here; use the result's parsedName and linkedIngredientId.
				// Actually, we need the trace's atom for ShouldReuse; skip this for now.
			}
			_error.WriteLine($"reuse lines: {reuseLines.Count} (ShouldReuse stats deferred)");
		}

		// Row-choice-tier direction.
		var tierLines = results.Where(r => r.Relation == AutoWrongClassifier.RelationRowChoiceTier).ToList();
		if (tierLines.Count > 0)
		{
			var keyHigher = tierLines.Count(r => TierRank(r.KeyTier) > TierRank(r.AcceptedTier));
			var accHigher = tierLines.Count - keyHigher;
			_error.WriteLine($"row-choice-tier: key higher={keyHigher} accepted higher={accHigher}");
		}

		// Same-head-other-qualifier details.
		var qualLines = results.Where(r => r.Relation == AutoWrongClassifier.RelationSameHeadOtherQualifier
			&& (r.KeyOnlyQualifiers?.Count > 0 == true || r.AcceptedOnlyQualifiers?.Count > 0 == true)).ToList();
		foreach (var r in qualLines)
		{
			var keyStr = string.Join(' ', r.KeyOnlyQualifiers ?? Array.Empty<string>());
			var accStr = string.Join(' ', r.AcceptedOnlyQualifiers ?? Array.Empty<string>());
			_error.WriteLine($"qualdiff: {r.HoldoutId}#{r.LineIndex} keyOnly=[{keyStr}] acceptedOnly=[{accStr}]");
		}
	}

	private static int TierRank(string tier) => tier switch
	{
		"Foundation" => 4,
		"SrLegacy" => 3,
		"Survey" => 2,
		"Branded" => 1,
		_ => 0,
	};

	private string FoldParsedName(string parsedName) =>
		string.Join(' ', Array.ConvertAll(
			parsedName.Split(' ', StringSplitOptions.RemoveEmptyEntries))
			.Select(t => IngredientLineResolver.SingularizeToken(t.ToLowerInvariant())));
}
